<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EngineerLaunch — Find Your Next Opportunity</title>
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
:root{--blue:#1769ff;--ink:#17233c;--muted:#697890;--line:#e1e7f0;--soft:#f7f9fc}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--soft);color:var(--ink);font-family:Inter,system-ui,sans-serif}a{text-decoration:none;color:inherit}button,input,select{font:inherit}.navbar{height:72px;padding:0 3%;display:flex;align-items:center;position:sticky;top:0;z-index:20;background:#fff;border-bottom:1px solid #e8edf5}.logo{font-size:24px;font-weight:800;color:var(--ink)}.logo b{color:var(--blue)}.nav-links{display:flex;gap:28px;margin-left:50px}.nav-links a,.nav-right a{color:#5c6980;font-size:14px;font-weight:600}.nav-links a:hover,.nav-right a:hover{color:var(--blue)}.nav-right{display:flex;align-items:center;gap:18px;margin-left:auto}.signup{padding:10px 16px;border-radius:8px;border:1px solid var(--blue);color:var(--blue)!important}.hero{padding:62px 6%;background:radial-gradient(circle at 85% 20%,rgba(23,105,255,.13),transparent 35%),linear-gradient(135deg,#f8fbff,#eef5ff);border-bottom:1px solid #e6edf7}.hero-inner,.container{max-width:1180px;margin:auto}.hero-label{display:inline-flex;padding:7px 13px;border:1px solid #dce6f5;border-radius:30px;background:#fff;color:var(--blue);font-size:12px;font-weight:700}.hero h1{max-width:780px;margin:18px 0 14px;font-size:clamp(38px,5vw,56px);line-height:1.08;letter-spacing:-1.7px}.hero h1 span{color:var(--blue)}.hero-copy{max-width:680px;color:var(--muted);font-size:16px;line-height:1.7}.search-box{display:grid;grid-template-columns:1fr .75fr auto;max-width:930px;margin-top:27px;padding:8px;border:1px solid #dce4ef;border-radius:14px;background:#fff;box-shadow:0 15px 40px rgba(28,55,95,.10)}.search-field{display:flex;align-items:center;gap:10px;padding:8px 15px;border-right:1px solid #e5eaf2}.search-field input{width:100%;padding:7px;border:0;outline:0;color:var(--ink)}.search-button{padding:0 26px;border:0;border-radius:10px;background:var(--blue);color:#fff;font-weight:700;cursor:pointer}.hero-stats{display:flex;gap:44px;flex-wrap:wrap;margin-top:28px}.stat strong{display:block;font-size:22px}.stat span{color:#758198;font-size:12px}.container{padding:44px 0 75px}.section-header,.job-toolbar{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:20px}.section-header h2,.job-toolbar h2{margin:0;font-size:26px}.section-header p,.job-toolbar p{margin:5px 0 0;color:#7a879c;font-size:13px}.company-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:12px}.company-card{padding:18px 10px;border:1px solid var(--line);border-radius:12px;background:#fff;text-align:center;cursor:pointer;transition:.2s}.company-card:hover,.company-card.active{transform:translateY(-3px);border-color:var(--blue);box-shadow:0 10px 25px rgba(28,55,95,.09)}.company-logo,.job-logo{display:grid;place-items:center;background:#f0f5ff;color:var(--blue);font-weight:800}.company-logo{width:43px;height:43px;margin:0 auto 10px;border-radius:10px}.company-name{font-size:12px;font-weight:700}.company-jobs{margin-top:4px;color:#8994a8;font-size:11px}.jobs-section{margin-top:58px}.tabs{display:flex;gap:8px}.tab{padding:9px 15px;border:1px solid #dfe6f0;border-radius:30px;background:#fff;color:#647189;font-size:12px;font-weight:600;cursor:pointer}.tab.active{background:#172b4d;color:#fff;border-color:#172b4d}.jobs-layout{display:grid;grid-template-columns:245px 1fr;gap:24px;align-items:start}.filters{position:sticky;top:92px;padding:20px;border:1px solid var(--line);border-radius:14px;background:#fff}.filters h3{margin:0 0 15px;font-size:15px}.filter-group{padding:14px 0;border-top:1px solid #edf0f5}.filter-title{margin-bottom:8px;font-size:12px;font-weight:700}.filters select{width:100%;padding:10px;border:1px solid #dfe6f0;border-radius:8px;background:#fff;color:#65728a;font-size:12px}.clear{width:100%;margin-top:8px;padding:10px;border:1px solid var(--blue);border-radius:8px;background:#fff;color:var(--blue);font-weight:700;cursor:pointer}.jobs-list{display:grid;gap:14px}.job-card{padding:22px;border:1px solid var(--line);border-radius:14px;background:#fff;transition:.2s}.job-card:hover{transform:translateY(-3px);border-color:#a9c6ff;box-shadow:0 12px 30px rgba(32,59,100,.08)}.job-top{display:flex;justify-content:space-between;gap:18px}.company-info{display:flex;gap:13px}.job-logo{flex:none;width:46px;height:46px;border-radius:10px}.company-small{margin-bottom:6px;color:var(--blue);font-size:11px;font-weight:800;text-transform:uppercase}.job-title{margin:0 0 8px;font-size:18px}.job-meta{display:flex;gap:14px;flex-wrap:wrap;color:#76839a;font-size:12px}.job-description{display:-webkit-box;overflow:hidden;-webkit-line-clamp:2;-webkit-box-orient:vertical;margin:16px 0;color:#7b879b;font-size:12px;line-height:1.65}.job-bottom{display:flex;justify-content:space-between;align-items:center;gap:16px;padding-top:15px;border-top:1px solid #edf0f5}.tags{display:flex;gap:7px;flex-wrap:wrap}.tag{padding:6px 9px;border-radius:6px;background:#f4f7fb;color:#66738a;font-size:10px;font-weight:600}.apply{padding:9px 14px;border-radius:7px;background:var(--blue);color:#fff;font-size:11px;font-weight:700;white-space:nowrap}.empty{padding:35px;border:1px dashed #ccd6e5;border-radius:13px;text-align:center;color:#697890;background:#fff}.journey{margin-top:65px}.journey-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.journey-card{display:block;padding:23px;border:1px solid var(--line);border-radius:14px;background:#fff;transition:.2s}.journey-card:hover{transform:translateY(-4px);border-color:var(--blue);box-shadow:0 15px 32px rgba(23,105,255,.10)}.journey-card b{display:grid;place-items:center;width:42px;height:42px;margin-bottom:14px;border-radius:10px;background:var(--blue);color:#fff}.journey-card h3{margin:0 0 8px}.journey-card p{color:var(--muted);font-size:13px;line-height:1.6}.journey-card span{color:var(--blue);font-size:13px;font-weight:700}@media(max-width:1000px){.company-grid{grid-template-columns:repeat(3,1fr)}.jobs-layout{grid-template-columns:1fr}.filters{position:static}.nav-links{gap:14px;margin-left:25px}}@media(max-width:720px){.navbar{padding:0 18px}.nav-links{display:none}.hero{padding:44px 20px}.search-box{grid-template-columns:1fr}.search-field{border-right:0;border-bottom:1px solid #e5eaf2}.search-button{height:48px}.container{padding:35px 20px}.company-grid{grid-template-columns:repeat(2,1fr)}.job-toolbar,.section-header,.job-bottom{align-items:flex-start;flex-direction:column}.tabs{width:100%;overflow:auto}.journey-grid{grid-template-columns:1fr}}
.company-logo,.job-logo{position:relative;overflow:hidden}.company-logo img,.job-logo img{width:72%;height:72%;object-fit:contain}.logo-fallback{display:grid;place-items:center;width:100%;height:100%}
</style></head><body>
<nav class="navbar"><a class="logo" href="/">Engineer<b>Launch</b></a><div class="nav-links"><a href="#jobs">Find Jobs</a><a href="#companies">Companies</a><a href="/learn">Learning</a><a href="/practice">Practice</a><a href="/about">About Us</a></div><div class="nav-right">@auth<a href="/dashboard">Dashboard</a>@else<a href="/login">Login</a><a class="signup" href="/register">Sign up</a>@endauth</div></nav>
<header class="hero"><div class="hero-inner"><div class="hero-label">✦ <span id="available-label">Loading verified opportunities…</span></div><h1>Find work that <span>moves you forward.</span></h1><p class="hero-copy">Discover current roles from supported official company career sources. Search by title, technology, company and location, then apply at the original employer website.</p><form class="search-box" id="search-form"><label class="search-field">⌕<input id="keyword" placeholder="Job title, skill or company" aria-label="Job title, skill or company"></label><label class="search-field">⌖<input id="location" placeholder="City, state or remote" aria-label="Location"></label><button class="search-button">Search Jobs</button></form><div class="hero-stats"><div class="stat"><strong id="job-count">—</strong><span>Active jobs</span></div><div class="stat"><strong id="company-count">—</strong><span>Companies hiring</span></div><div class="stat"><strong id="technology-count">—</strong><span>Technology skills</span></div></div></div></header>
<main class="container"><section id="companies"><div class="section-header"><div><h2>Explore top companies</h2><p>Companies with synchronized active openings</p></div><button class="tab" id="all-companies">All companies</button></div><div class="company-grid" id="company-grid"><div class="empty">Loading companies…</div></div></section>
<section class="jobs-section" id="jobs"><div class="job-toolbar"><div><h2>Latest opportunities</h2><p id="result-count">Loading current roles…</p></div><div class="tabs"><button class="tab active" data-sort="posted_at">Newest</button><button class="tab" data-sort="views">Popular</button><button class="tab" data-preset="graduate">Graduate</button><button class="tab" data-preset="remote">Remote</button></div></div><div class="jobs-layout"><aside class="filters"><h3>Filter jobs</h3><div class="filter-group"><div class="filter-title">Work mode</div><select id="work-mode"><option value="">Any work mode</option><option value="remote">Remote</option><option value="hybrid">Hybrid</option><option value="office">On-site</option></select></div><div class="filter-group"><div class="filter-title">Employment type</div><select id="job-type"><option value="">Any employment type</option><option>Full-time</option><option>Part-time</option><option>Contract</option><option>Internship</option></select></div><div class="filter-group"><div class="filter-title">Experience</div><select id="experience"><option value="">Any experience</option><option value="0">Fresher</option><option value="1">1 year</option><option value="3">3 years</option><option value="5">5 years</option><option value="7">7 years</option><option value="10">10+ years</option></select></div><div class="filter-group"><div class="filter-title">Posted</div><select id="posted"><option value="">Any date</option><option value="7">Last 7 days</option><option value="15">Last 15 days</option><option value="25">Last 25 days</option><option value="35">Last 35 days</option></select></div><div class="filter-group"><div class="filter-title">Role family</div><select id="role"><option value="">Any role</option><option value="software-development">Software development</option><option value="frontend">Frontend</option><option value="backend">Backend</option><option value="full-stack">Full stack</option><option value="quality-testing">Testing & QA</option><option value="devops-cloud">DevOps & cloud</option><option value="data-ai">Data & AI</option><option value="security">Security</option></select></div><div class="filter-group"><div class="filter-title">Technology</div><select id="technology"><option value="">Any technology</option></select></div><button class="clear" id="clear-filters" type="button">Clear filters</button></aside><div class="jobs-list" id="jobs-list"><div class="empty">Loading opportunities…</div></div></div></section>
<section class="journey"><div class="section-header"><div><h2>Your complete career journey</h2><p>Everything works from this one homepage.</p></div></div><div class="journey-grid"><a class="journey-card" href="/about"><b>01</b><h3>About EngineerLaunch</h3><p>Our mission, platform model and promise to job seekers.</p><span>Read about us →</span></a><a class="journey-card" href="/learn"><b style="background:#7c3aed">02</b><h3>Learning & interview preparation</h3><p>Java, Spring Boot, Laravel, DSA, system design, ML and data science.</p><span>Start learning →</span></a><a class="journey-card" href="/practice"><b style="background:#0891b2">03</b><h3>Live practice editor</h3><p>Write and run browser-safe HTML, CSS and JavaScript.</p><span>Open editor →</span></a></div></section></main>
<script>
const state={company:'',sort:'posted_at',preset:''};
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
async function api(path){const response=await fetch(path,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('Request failed');return response.json()}
function initials(name){return String(name||'CO').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function companyLogo(company){const fallback=`<span class="logo-fallback">${esc(initials(company?.name))}</span>`;if(!company?.website)return fallback;const source=`https://www.google.com/s2/favicons?domain_url=${encodeURIComponent(company.website)}&sz=128`;return `<img src="${esc(source)}" alt="${esc(company.name)} logo" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.display='none';this.nextElementSibling.style.display='grid'"><span class="logo-fallback" style="display:none">${esc(initials(company.name))}</span>`}
function jobCard(job){const tags=[...(job.technologies||[]).map(x=>x.name),...(job.categories||[]).map(x=>x.name)].slice(0,5);const description=String(job.description||'Review the complete role requirements on the official company careers page.').replace(/<[^>]*>/g,' ');return `<article class="job-card"><div class="job-top"><div class="company-info"><div class="job-logo">${esc(initials(job.company?.name))}</div><div><div class="company-small">${esc(job.company?.name||'Company')}</div><h3 class="job-title">${esc(job.title)}</h3><div class="job-meta"><span>📍 ${esc(job.location||'Not specified')}</span><span>● ${esc(job.job_type||'Full-time')}</span>${job.work_mode?`<span>● ${esc(job.work_mode)}</span>`:''}</div></div></div></div><p class="job-description">${esc(description)}</p><div class="job-bottom"><div class="tags">${tags.map(tag=>`<span class="tag">${esc(tag)}</span>`).join('')}</div><a class="apply" href="${esc(job.external_url||job.company?.careers_url||'#')}" target="_blank" rel="noopener noreferrer">View official job →</a></div></article>`}
function parameters(){const p=new URLSearchParams({per_page:20,sort_by:state.sort,sort_order:'desc'});const values={q:$('#keyword').value.trim(),location:$('#location').value.trim(),company_id:state.company,work_mode:$('#work-mode').value,job_type:$('#job-type').value,experience_years:$('#experience').value,posted_within_days:$('#posted').value,role_family:$('#role').value,technology_id:$('#technology').value};if(state.preset==='graduate')values.q='graduate';if(state.preset==='remote')values.work_mode='remote';Object.entries(values).forEach(([key,value])=>{if(value!==''&&value!=null)p.set(key,value)});return p}
async function loadJobs(){const list=$('#jobs-list');list.innerHTML='<div class="empty">Loading opportunities…</div>';try{const payload=await api('/api/jobs?'+parameters());$('#result-count').textContent=`${payload.pagination.total.toLocaleString()} matching roles`;list.innerHTML=payload.data.length?payload.data.map(jobCard).join(''):'<div class="empty"><strong>No exact matches.</strong><br>Try fewer keywords or clear one of the filters.</div>'}catch(error){list.innerHTML='<div class="empty">Jobs could not be loaded. Please retry.</div>'}}
async function initialize(){try{const[stats,companies,technologies]=await Promise.all([api('/api/jobs/stats'),api('/api/companies?per_page=100'),api('/api/technologies?per_page=100')]);const s=stats.data;$('#job-count').textContent=s.total_jobs.toLocaleString();$('#company-count').textContent=s.total_companies.toLocaleString();$('#technology-count').textContent=s.total_technologies.toLocaleString();$('#available-label').textContent=`${s.total_jobs.toLocaleString()} verified opportunities available`;$('#company-grid').innerHTML=companies.data.slice(0,12).map(company=>`<button class="company-card" data-company="${company.id}"><span class="company-logo">${esc(initials(company.name))}</span><span class="company-name">${esc(company.name)}</span><span class="company-jobs">${company.active_jobs_count.toLocaleString()} jobs</span></button>`).join('');$('#technology').insertAdjacentHTML('beforeend',technologies.data.map(item=>`<option value="${item.id}">${esc(item.name)}</option>`).join(''))}catch(error){$('#company-grid').innerHTML='<div class="empty">Company data unavailable.</div>'}loadJobs()}
$('#search-form').addEventListener('submit',event=>{event.preventDefault();state.company='';state.preset='';loadJobs();$('#jobs').scrollIntoView()});$('#company-grid').addEventListener('click',event=>{const card=event.target.closest('[data-company]');if(!card)return;document.querySelectorAll('.company-card').forEach(x=>x.classList.remove('active'));card.classList.add('active');state.company=card.dataset.company;loadJobs();$('#jobs').scrollIntoView()});$('#all-companies').addEventListener('click',()=>{state.company='';document.querySelectorAll('.company-card').forEach(x=>x.classList.remove('active'));loadJobs()});document.querySelectorAll('.tab[data-sort],.tab[data-preset]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.job-toolbar .tab').forEach(x=>x.classList.remove('active'));button.classList.add('active');state.sort=button.dataset.sort||'posted_at';state.preset=button.dataset.preset||'';loadJobs()}));['work-mode','job-type','experience','posted','role','technology'].forEach(id=>$('#'+id).addEventListener('change',loadJobs));$('#clear-filters').addEventListener('click',()=>{['work-mode','job-type','experience','posted','role','technology'].forEach(id=>$('#'+id).value='');$('#keyword').value='';$('#location').value='';state.company='';state.preset='';loadJobs()});initialize();
</script><script>
let companyLogoDirectory={byId:{},byName:{}};
function paintCompanyLogos(){document.querySelectorAll('.company-card[data-company]').forEach(card=>{const company=companyLogoDirectory.byId[card.dataset.company],target=card.querySelector('.company-logo');if(company&&target)target.innerHTML=companyLogo(company)});document.querySelectorAll('.job-card').forEach(card=>{const name=card.querySelector('.company-small')?.textContent.trim().toLowerCase(),company=companyLogoDirectory.byName[name],target=card.querySelector('.job-logo');if(company&&target)target.innerHTML=companyLogo(company)})}
api('/api/companies?per_page=100').then(payload=>{payload.data.forEach(company=>{companyLogoDirectory.byId[String(company.id)]=company;companyLogoDirectory.byName[String(company.name).toLowerCase()]=company});paintCompanyLogos();new MutationObserver(paintCompanyLogos).observe(document.querySelector('#jobs-list'),{childList:true})}).catch(()=>{});
</script></body></html>
